        fwd = 0.7
    else:
        fwd = 1.0
    if r > arena.radius - 1.5:
        fwd = fwd * 0.7
    left = fwd - turn
    right = fwd + turn
    if left > 1.0:
        left = 1.0
    elif left < -1.0:
        left = -1.0
    if right > 1.0:
        right = 1.0
    elif right < -1.0:
