def weapons(me, enemy, arena):
    cmds = []
    if not me.righting:
        if me.inverted or me.on_side:
            cmds.append(self_right())
    if not me.can_drive:
        return cmds
    w = me.weapons.get("front")
    if w is not None and w.get("type") == "clamp":
        state = w.get("state")
        dx = enemy.x - me.x
        dy = enemy.y - me.y
        h = radians(me.heading)
        ch = cos(h)
        sh = sin(h)
        fwd_comp = dx * ch + dy * sh
        lat_comp = -dx * sh + dy * ch
        reach = w.get("reach", 0.6)
        front_dist = me.length / 2.0
        in_zone = (fwd_comp > front_dist - 0.05 and fwd_comp < front_dist + reach + 0.05 and abs(lat_comp) < 0.4 * me.width + 0.05)
        if state == "open":
            if in_zone and not enemy.airborne:
                cmds.append(grab("front"))
        elif state == "closed":
            cmds.append(release("front"))
    return cmds

